css:
@media screen, print {
  .print-format {
    padding: 0 !important;
    margin: 0 !important;
    max-width: none !important;
    width: 100% !important;
    box-sizing: border-box !important;
  }
}
.print-format .fk-im-sheet {
  font-family: Inter, Arial, Helvetica, sans-serif;
  font-size: 9pt;
  color: #111827;
  padding: 8mm 12mm 10mm;
  box-sizing: border-box;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}
.print-format .fk-im-header-qr {
  text-align: center;
  padding: 4px 0 2px;
}
.print-format .fk-im-qr-wrap img {
  width: 120px;
  height: 120px;
  display: inline-block;
}
.print-format .fk-im-section-break {
  height: 0;
  border: 0;
  border-top: 1px solid #c5d9e4;
  margin: 12px 0;
}
.print-format .fk-im-info-box {
  border: 2px solid #7ba7bc;
  border-radius: 16px;
  padding: 14px 0 12px;
  overflow: hidden;
}
.print-format .fk-im-info-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}
.print-format .fk-im-info-table td {
  vertical-align: top;
  padding: 0;
}
.print-format .fk-im-info-cell-left {
  width: 58%;
  padding: 0 18px;
}
.print-format .fk-im-info-cell-right {
  width: 42%;
  padding: 0 18px 0 22px;
  border-left: 1px solid #7ba7bc;
}
.print-format .fk-im-field-row {
  display: table;
  width: 100%;
  table-layout: fixed;
  margin-bottom: 11px;
}
.print-format .fk-im-field-row:last-child {
  margin-bottom: 0;
}
.print-format .fk-im-field-row .fk-im-label {
  display: table-cell;
  width: 1%;
  white-space: nowrap;
  padding-right: 8px;
  vertical-align: baseline;
}
.print-format .fk-im-field-row .fk-im-line,
.print-format .fk-im-field-row .fk-im-date-line {
  display: table-cell;
  width: 99%;
  vertical-align: baseline;
}
.print-format .fk-im-label {
  font-size: 8pt;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: #1e3a5f;
  white-space: nowrap;
  flex-shrink: 0;
}
.print-format .fk-im-line,
.print-format .fk-im-date-line,
.print-format .fk-im-sign-line {
  flex: 1;
  border-bottom: 1px solid #1e3a5f;
  min-height: 14px;
  font-size: 8pt;
  line-height: 1.4;
  color: #111827;
}
.print-format .fk-im-notes-head {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 10px;
}
.print-format .fk-im-notes-icon {
  display: inline-flex;
  line-height: 0;
}
.print-format .fk-im-notes-icon svg {
  width: 16px;
  height: 16px;
  fill: #1e3a5f;
}
.print-format .fk-im-note-line {
  border-bottom: 1px solid #1e3a5f;
  height: 16px;
  margin-bottom: 10px;
}
.print-format .fk-im-note-line:last-child {
  margin-bottom: 0;
}
.print-format .fk-im-body {
  margin-top: 2px;
}
.print-format .fk-im-section {
  margin-bottom: 12px;
  page-break-inside: avoid;
}
.print-format .fk-im-section-title {
  color: #fff;
  font-size: 8pt;
  font-weight: 700;
  letter-spacing: 0.03em;
  padding: 6px 10px;
  margin-bottom: 0;
}
.print-format .fk-im-assembly { background: #1e3a5f; }
.print-format .fk-im-fitting { background: #2563eb; }
.print-format .fk-im-extra { background: #6b7280; }
.print-format .fk-im-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}
.print-format .fk-im-table th,
.print-format .fk-im-table td {
  border: 1px solid #9ca3af;
  padding: 5px 6px;
  vertical-align: top;
  word-wrap: break-word;
}
.print-format .fk-im-table th {
  background: #f3f4f6;
  font-size: 7pt;
  font-weight: 700;
  text-align: center;
}
.print-format .fk-im-table th:nth-child(1),
.print-format .fk-im-table th:nth-child(4),
.print-format .fk-im-table th:nth-child(5),
.print-format .fk-im-table th:nth-child(6),
.print-format .fk-im-table th:nth-child(7) { width: 7%; }
.print-format .fk-im-table th:nth-child(2) { width: 24%; }
.print-format .fk-im-table th:nth-child(3) { width: 18%; }
.print-format .fk-im-table th:nth-child(8) { width: 16%; }
.print-format .fk-im-center { text-align: center; }
.print-format .fk-im-check { font-size: 11pt; line-height: 1; }
.print-format .fk-im-footer {
  margin-top: 16px;
  page-break-inside: avoid;
}
.print-format .fk-im-defects-box {
  border: 2px solid #7ba7bc;
  border-radius: 16px;
  padding: 12px 18px 14px;
  margin-bottom: 14px;
}
.print-format .fk-im-footer-title {
  font-size: 8pt;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: #1e3a5f;
  margin-bottom: 10px;
}
.print-format .fk-im-footer-line {
  border-bottom: 1px solid #1e3a5f;
  height: 16px;
  margin-bottom: 10px;
}
.print-format .fk-im-footer-line:last-child {
  margin-bottom: 0;
}
.print-format .fk-im-signoff-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}
.print-format .fk-im-signoff-table td {
  vertical-align: bottom;
  padding: 0;
}
.print-format .fk-im-sign-cell-left {
  width: 68%;
  padding-right: 22px;
}
.print-format .fk-im-sign-cell-right {
  width: 32%;
  padding-left: 22px;
  border-left: 1px solid #7ba7bc;
}
.print-format .fk-im-sign-col {
  display: table;
  width: 100%;
  table-layout: fixed;
}
.print-format .fk-im-sign-col .fk-im-label {
  display: table-cell;
  width: 1%;
  white-space: nowrap;
  padding-right: 8px;
  vertical-align: baseline;
}
.print-format .fk-im-sign-col .fk-im-sign-line,
.print-format .fk-im-sign-col .fk-im-date-line {
  display: table-cell;
  width: 99%;
  vertical-align: baseline;
}
